// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.csf;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.Arrays;
import java.util.Random;

import org.junit.jupiter.api.Test;

class CsfRadixDirectoryTest {

	@Test
	void handlesEmptySingletonEndpointsGapsAndEmptyBuckets() {
		assertThat(route(new long[0], 7)).isEqualTo(-1);
		assertThat(route(new long[] { 10 }, 9)).isEqualTo(-1);
		assertThat(route(new long[] { 10 }, 10)).isZero();
		assertThat(route(new long[] { 10 }, 11)).isZero();

		long[] fences = { 10, 11, 1_000, 1_001 };
		Directory directory = directory(fences);
		assertThat(route(directory, 9)).isEqualTo(-1);
		assertThat(route(directory, 10)).isZero();
		assertThat(route(directory, 11)).isEqualTo(1);
		assertThat(route(directory, 12)).isEqualTo(1);
		assertThat(route(directory, 999)).isEqualTo(1);
		assertThat(route(directory, 1_000)).isEqualTo(2);
		assertThat(route(directory, 1_001)).isEqualTo(3);
		assertThat(route(directory, 1_002)).isEqualTo(3);
		assertThat(hasEmptyBucket(directory.bounds)).isTrue();
	}

	@Test
	void routesTypedClusteredAndSignedBoundaryRanges() {
		long[] typed = new long[1_024];
		for (int i = 0; i < typed.length; i++) {
			long typeTag = i % 5;
			typed[i] = ((long) i << 12) | typeTag;
		}
		assertOracleAgreement(typed, new Random(0x7479_7065L), 20_000);

		long[] clustered = new long[1_024];
		for (int i = 0; i < clustered.length; i++) {
			clustered[i] = ((long) (i >>> 5) << 48) | ((long) (i & 31) << 7) | 3;
		}
		assertOracleAgreement(clustered, new Random(0x636c_7573L), 20_000);

		long[] signedBoundary = {
				Long.MAX_VALUE - 100,
				Long.MAX_VALUE,
				Long.MIN_VALUE,
				Long.MIN_VALUE + 100,
				-2,
				-1
		};
		assertOracleAgreement(signedBoundary, new Random(0x7369_676eL), 20_000);
	}

	@Test
	void returnsFirstIdenticalContinuationFence() {
		long[] fences = { 10, 20, 20, 20, 30, 30, 40 };
		assertThat(route(fences, 20)).isEqualTo(1);
		assertThat(route(fences, 21)).isEqualTo(3);
		assertThat(route(fences, 30)).isEqualTo(4);
		assertThat(route(fences, 31)).isEqualTo(5);
	}

	@Test
	void randomizedRoutingMatchesUnsignedPredecessorOracle() {
		Random random = new Random(0x5241_4449_584cL);
		for (int round = 0; round < 200; round++) {
			int size = 2 + random.nextInt(4_095);
			long[] fences = new long[size];
			for (int i = 0; i < size; i++) {
				fences[i] = random.nextLong();
			}
			sortUnsigned(fences);
			for (int i = 17; i < size; i += 97) {
				fences[i] = fences[i - 1];
			}
			assertOracleAgreement(fences, random, 500);
		}
	}

	@Test
	void sizesMaximumShardAndRejectsOverflow() {
		assertThat(CsfRadixDirectory.bucketCount(4_096)).isEqualTo(4_096);
		assertThat(CsfRadixDirectory.boundsLength(4_096)).isEqualTo(4_097);
		assertThat(CsfRadixDirectory.nativeShortBoundsBytes(4_096)).isEqualTo(8_194);
		assertThatThrownBy(() -> CsfRadixDirectory.bucketCount((1 << 30) + 1))
				.isInstanceOf(IllegalArgumentException.class);
		assertThatThrownBy(() -> CsfRadixDirectory.totalBoundsLength(new int[] { 1 << 30, 1 << 30 }))
				.isInstanceOf(ArithmeticException.class);
	}

	private static void assertOracleAgreement(long[] fences, Random random, int queries) {
		Directory directory = directory(fences);
		for (long fence : fences) {
			assertThat(route(directory, fence)).isEqualTo(unsignedPredecessor(fences, fence));
		}
		for (int query = 0; query < queries; query++) {
			long value = random.nextLong();
			assertThat(route(directory, value)).isEqualTo(unsignedPredecessor(fences, value));
		}
	}

	private static int unsignedPredecessor(long[] fences, long value) {
		int floor = -1;
		for (int i = 0; i < fences.length; i++) {
			int comparison = Long.compareUnsigned(fences[i], value);
			if (comparison == 0) {
				return i;
			}
			if (comparison > 0) {
				return floor;
			}
			floor = i;
		}
		return floor;
	}

	private static int route(long[] fences, long value) {
		return route(directory(fences), value);
	}

	private static int route(Directory directory, long value) {
		return CsfRadixDirectory.floor(directory.fences, 0, directory.fences.length, value, directory.bounds,
				directory.descriptor);
	}

	private static Directory directory(long[] fences) {
		int[] bounds = new int[CsfRadixDirectory.boundsLength(fences.length)];
		long descriptor = 0;
		if (fences.length >= 2) {
			descriptor = CsfRadixDirectory.descriptor(0, fences.length, fences[0], fences[fences.length - 1]);
			CsfRadixDirectory.buildBounds(fences, 0, fences.length, bounds, 0, descriptor);
		}
		return new Directory(fences, bounds, descriptor);
	}

	private static boolean hasEmptyBucket(int[] bounds) {
		for (int i = 0; i + 1 < bounds.length; i++) {
			if (bounds[i] == bounds[i + 1]) {
				return true;
			}
		}
		return false;
	}

	private static void sortUnsigned(long[] values) {
		Long[] boxed = Arrays.stream(values).boxed().toArray(Long[]::new);
		Arrays.sort(boxed, Long::compareUnsigned);
		for (int i = 0; i < values.length; i++) {
			values[i] = boxed[i];
		}
	}

	private record Directory(long[] fences, int[] bounds, long descriptor) {
	}
}
